begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('ab000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','self-service-'||i||'@example.test','',case when i=2 then null else now() end,now(),now() from generate_series(1,3)i;
select set_config('test.trial_payload','{"fullName":"Responsável sintético","ministry":"Ministério sintético identidade","headquarters":"Sede sintética","pastor":"Pastor sintético","phone":"11999999999","city":"São Paulo","state":"SP","units":"1","accepted":true}',true);
select ok(not prosecdef,'bootstrap continua invoker') from pg_proc where oid='public.bootstrap_organization(text,text,text,text)'::regprocedure;
select ok(not prosecdef,'cadastro de demonstração continua invoker') from pg_proc where oid='public.register_organization_trial(jsonb)'::regprocedure;
select ok(not has_function_privilege('anon','private.require_confirmed_self_service_email()','EXECUTE'),'visitante não executa verificação interna');
select ok(has_function_privilege('authenticated','private.require_confirmed_self_service_email()','EXECUTE'),'invoker autenticado verifica apenas sua própria identidade');
select ok(not has_table_privilege('authenticated','auth.users','SELECT'),'verificação não abre leitura da tabela de autenticação');
select is(to_regprocedure('public.require_confirmed_self_service_email()'),null::regprocedure,'verificador não tem endpoint público');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select private.require_confirmed_self_service_email()$$,'28000','authentication_required','identidade ausente não é aceita');
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000002","email":"forged-confirmed@example.test","email_confirmed_at":"2026-10-16","is_anonymous":false,"role":"authenticated"}',true);
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','confirmação forjada no token não substitui o banco');
select throws_ok($$select public.bootstrap_organization('Sem confirmação','identity-unconfirmed','Sede')$$,'42501','self_service_identity_unavailable','bootstrap direto exige confirmação');
select throws_ok($$select public.register_organization_trial(current_setting('test.trial_payload')::jsonb)$$,'42501','self_service_identity_unavailable','cadastro direto exige confirmação');
select throws_ok($$insert into public.organizations(name,slug) values('Gravação direta','identity-direct-unconfirmed')$$,'42501','self_service_identity_unavailable','INSERT direto não contorna confirmação');
reset role;
select is((select count(*) from public.organizations where bootstrap_user_id='ab000000-0000-4000-8000-000000000002'),0::bigint,'recusas não provisionam ministério');
update auth.users set email_confirmed_at=now(),banned_until=now()+interval '1 day' where id='ab000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','conta suspensa na autenticação não cria ambiente');
reset role;
update auth.users set banned_until=null,deleted_at=now() where id='ab000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','conta removida logicamente não usa token antigo');
reset role;
update auth.users set deleted_at=null,is_anonymous=true where id='ab000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','conta anônima real não se torna definitiva pelo token');
reset role;
update auth.users set is_anonymous=false,email=null where id='ab000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','conta sem e-mail não provisiona ministério');
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000099","email":"old@example.test","role":"authenticated"}',true);
select throws_ok($$select private.require_confirmed_self_service_email()$$,'42501','self_service_identity_unavailable','conta inexistente não utiliza token antigo');
reset role;
update auth.users set email='current-confirmed@example.test' where id='ab000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000001","email":"stale@example.test","role":"authenticated"}',true);
select is(private.require_confirmed_self_service_email(),'current-confirmed@example.test','verificação usa e-mail atual confirmado, não a cópia do token');
select lives_ok($$select public.register_organization_trial(current_setting('test.trial_payload')::jsonb)$$,'cadastro legítimo mantém criação transacional');
select is((select email from public.saas_trial_registrations where user_id=auth.uid()),'current-confirmed@example.test','registro da demonstração recebe e-mail atual');
select is((select u.email from public.organization_units u join public.saas_trial_registrations r on r.organization_id=u.organization_id where r.user_id=auth.uid() and u.unit_type='headquarters'),'current-confirmed@example.test','contato inicial da sede recebe e-mail atual');
select is((public.register_organization_trial('{}')->>'alreadyCreated')::boolean,true,'repetição legítima retoma sem duplicar');
select is((select count(*) from public.saas_trial_registrations where user_id=auth.uid()),1::bigint,'uma única demonstração por conta');
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000003","email":"other-fake@example.test","role":"authenticated"}',true);
select lives_ok($$select public.bootstrap_organization('Bootstrap confirmado','identity-confirmed-bootstrap','Sede sintética')$$,'bootstrap legítimo continua disponível');
select throws_ok($$insert into public.saas_trial_registrations(organization_id,user_id,full_name,email,phone,city,state,units_estimate,terms_version) select id,auth.uid(),'Pessoa sintética','forged@example.test','11999999999','São Paulo','SP',1,'teste-2026-10-14' from public.organizations where slug='identity-confirmed-bootstrap'$$,'42501','trial_registration_identity_mismatch','INSERT direto não fabrica e-mail do responsável');
select is((select count(*) from public.saas_trial_registrations where user_id=auth.uid()),0::bigint,'registro de e-mail falso não persiste');
select lives_ok($$insert into public.saas_trial_registrations(organization_id,user_id,full_name,email,phone,city,state,units_estimate,terms_version) select id,auth.uid(),'Pessoa sintética','self-service-3@example.test','11999999999','São Paulo','SP',1,'teste-2026-10-14' from public.organizations where slug='identity-confirmed-bootstrap'$$,'INSERT autorizado com identidade real permanece disponível');
select is(private.require_confirmed_self_service_email(),'self-service-3@example.test','verificador não retorna identidade de outra conta');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='ab000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000001","email":"stale@example.test","role":"authenticated"}',true);
select throws_ok($$select public.register_organization_trial('{}')$$,'42501','self_service_identity_unavailable','retomada de demonstração também exige conta válida');
reset role;
select is((select count(*) from public.saas_trial_registrations where user_id='ab000000-0000-4000-8000-000000000001'),1::bigint,'recusa não remove demonstração existente');
select * from finish();
rollback;
